IovSetDto IovSetDto::fromFsJson(const json &j) {
  IovSetDto iovSet;
  iovSet.loadFromJson(j);
  // int n = j.size();

  for (auto it = j.begin(); it != j.end(); ++it) {
    iovSet.resources.push_back(IovDto::fromJson(*it));
  }

  iovSet.setDataType("iovs");

  return iovSet;
}
